// The decision layer of SPEC T8, once for every transport: the conclusion of the T8 row for one
// classification (`classifyWireEvent` puts a wire event into its answer class), what one answer
// to `server/discover` means for the modern path, and the vocabulary every transport settles a
// request with (`WireAnswer`). The readings of a settled answer are in `answer-readings.ts`, what
// a transport writes in `composition.ts`, the rules by connection in `connection.ts`, the
// orchestration of `discover` in `discovery.ts`, and the authorization discovery in
// `authorization.ts`. A transport keeps only its wire and its in-flight table.
import type { JsonValue } from '@omne-harness/json-text'
import type { RequestMethod } from './composition.ts'
import { isObject, member, type JsonObject } from './json.ts'
import type {
  AnswerMalformed,
  AuthorizationDiscovery,
  NoAnswerCause,
  UnusableCause,
} from './outcomes.ts'
import { errorAnswerOf, peerIdentityOf, readDiscoverResult, type IdentityBound } from './readers.ts'
import type { TransportFailure, TransportMaterial } from './transport.ts'
import type { PeerIdentity } from './values.ts'
import {
  ERROR_CLASSES,
  HTTP_STATUS_CLASSES,
  classifyWireEvent,
  envelopeOf,
  supportedOf,
  type AnswerClass,
  type BodyClass,
  type ErrorClass,
  type HttpStatusClass,
  type RequestClass,
  type WireClassification,
  type WireContext,
} from './wire.ts'

/** The modern versions a transport speaks on `server/discover`, highest first: at least one. */
export type ProtocolVersions = readonly [string, ...string[]]

/** The two `server/discover` request classes. */
export const PROBE_REQUESTS: readonly RequestClass[] = ['discover', 'discover-retry']

/**
 * The request classes that Streamable HTTP sends once more, with a new id, after a broken
 * stream or a 2xx without an answer (T8 D15, O05). Not in the legacy HTTP+SSE mode.
 */
export const RESENT_REQUESTS: readonly RequestClass[] = [
  'discover',
  'discover-retry',
  'tools/list',
  'tasks/get',
]

export type { UnusableCause } from './outcomes.ts'

type NotSent = Extract<TransportFailure, { kind: 'not-sent' }>

/**
 * What a transport settles one request with: the T8 reading of the answer class, before the
 * request's own reader (T2, T6) is applied.
 * - `result`, `error`: the JSON-RPC answer. An `error` keeps its class; `error` is the error
 *   object, or the whole message when the envelope is not one of T2 (C02).
 * - `no-answer`: nothing readable came; `resend` says whether the row sends the request once more.
 * - `not-sent`: the request had no effect at the peer.
 * A `no-answer` and a `not-sent` other than `authorization-required` carry `unusable` (on the
 * `not-sent`, in its failure) when the transport is not usable any more as it hands the answer
 * over (T1); only this layer writes it (`settle`, `lineGoneAnswerOf`, `unusableAnswerOf`).
 * - `legacy-peer`: a `server/discover` answer that says the peer speaks a legacy revision only.
 * - `legacy-http`: `initialize` answered 4xx+plain: the legacy HTTP+SSE fallback may follow (I07).
 */
export type WireAnswer =
  | Readonly<{ kind: 'result'; result: JsonValue }>
  | Readonly<{ kind: 'error'; error: JsonValue; errorClass: ErrorClass }>
  | Readonly<{ kind: 'no-answer'; cause: NoAnswerCause; resend: boolean; unusable?: UnusableCause }>
  | Readonly<{ kind: 'not-sent'; failure: NotSent }>
  | Readonly<{ kind: 'legacy-peer' }>
  | Readonly<{ kind: 'legacy-http' }>

/**
 * The conclusion of a T8 row for one classification.
 * - `settle`: the request settles with `wire`; `unusable` names the cause every later request
 *   answers with when the row ends the transport, and `wire` carries it already.
 * - `authorization-required`: T4: the transport calls `reportRejection()` on the handle that
 *   authorized the request, discovers the authorization, and settles with `not-sent`.
 * - `wait`: the event was no answer to the request (`other`, `waiting`).
 */
export type AnswerConclusion =
  | Readonly<{ kind: 'settle'; wire: WireAnswer; unusable?: UnusableCause }>
  | Readonly<{ kind: 'authorization-required' }>
  | Readonly<{ kind: 'wait' }>

/** What one answer to `server/discover` means for the modern path (T3, T8 D rows). */
export type ProbeConclusion =
  | Readonly<{ kind: 'identity'; identity: PeerIdentity }>
  | Readonly<{ kind: 'retry'; version: string }>
  | Readonly<{ kind: 'final'; failure: TransportFailure }>
  /** The legacy path is tried; when it fails too, this failure is reported. */
  | Readonly<{ kind: 'fallback'; failure: TransportFailure }>
  /** The legacy path is tried; when it fails too, its own failure is reported. */
  | Readonly<{ kind: 'legacy-peer' }>

export const NOT_SENT_FAILURE: NotSent = { kind: 'not-sent', cause: 'connection-unavailable' }
const SESSION_ENDED: NotSent = { kind: 'not-sent', cause: 'session-ended' }
const NOT_SENT: WireAnswer = { kind: 'not-sent', failure: NOT_SENT_FAILURE }
const LEGACY_PEER: WireAnswer = { kind: 'legacy-peer' }
const LEGACY_HTTP: WireAnswer = { kind: 'legacy-http' }
export const ABANDONED: WireAnswer = { kind: 'no-answer', cause: 'abandoned', resend: false }
const WAIT: AnswerConclusion = { kind: 'wait' }
const AUTHORIZATION_REQUIRED: AnswerConclusion = { kind: 'authorization-required' }
const MODERN_ERROR_CLASSES: readonly ErrorClass[] = [
  '-32020',
  '-32021',
  '-32022+common',
  '-32022+modern',
  '-32022+legacy',
]

/** The failure of an answer that was read and found malformed (T7). */
export const malformed = (what: AnswerMalformed['what']): TransportFailure => ({
  kind: 'answer-malformed',
  what,
})

function settle(wire: WireAnswer, unusable?: UnusableCause): AnswerConclusion {
  return unusable === undefined
    ? { kind: 'settle', wire }
    : { kind: 'settle', wire: unusableAnswerOf(wire, unusable), unusable }
}

/**
 * The `not-sent` (`connection-unavailable`) of a request the transport did not take: with the
 * cause as the mark when the transport is not usable any more (T1, T8 "every later request").
 */
export function notSentFailureOf(unusable: UnusableCause | undefined): NotSent {
  return unusable === undefined
    ? NOT_SENT_FAILURE
    : { kind: 'not-sent', cause: 'connection-unavailable', unusable }
}

/**
 * T1, T8 "every later request": `wire` as a transport that is not usable any more hands it over,
 * for `cause`, the cause the transport recorded. The mark is the transport's state, not the
 * line's: a `no-answer` and a `not-sent` other than `authorization-required` carry `cause`, in
 * place of a mark they carried already; the cause of the request's own failure stays.
 *
 * A `not-sent` (`session-ended`) carries `session-ended` whatever `cause` is. Only T8 S07 gives
 * it, and S07 ends the transport for `session-ended`; a transport that died for another cause
 * first has settled every request on the line by then, so no transport hands one over for another
 * cause. The cell still needs a value: whether the mark is present decides whether a ready
 * connection is lost (S7), so the answer carries one, and the answer itself says the session
 * ended.
 *
 * A refused authorization, an answer of the peer and the two legacy readings are as they are: no
 * gone line gives them.
 */
export function unusableAnswerOf(wire: WireAnswer, cause: UnusableCause): WireAnswer {
  switch (wire.kind) {
    case 'no-answer':
      return { ...wire, unusable: cause }
    case 'not-sent': {
      const failure = wire.failure
      switch (failure.cause) {
        case 'authorization-required':
          return wire
        case 'session-ended':
          return { kind: 'not-sent', failure: { ...failure, unusable: 'session-ended' } }
        case 'connection-unavailable':
          return { kind: 'not-sent', failure: { ...failure, unusable: cause } }
        default: {
          const exhaustive: never = failure
          return exhaustive
        }
      }
    }
    case 'result':
    case 'error':
    case 'legacy-peer':
    case 'legacy-http':
      return wire
    default: {
      const exhaustive: never = wire
      return exhaustive
    }
  }
}

function brokenStream(resend: boolean): WireAnswer {
  return { kind: 'no-answer', cause: 'stream-broken', resend }
}

/** The request class of a request the transport sends; `retried` marks the second probe. */
export function requestClassOf(method: RequestMethod, retried: boolean): RequestClass {
  if (method === 'server/discover') return retried ? 'discover-retry' : 'discover'
  return method
}

// ---- The conclusion of a classification (T8) ----

/** The rows that read the exchange itself, not a message: X01, X02, S01–S07, D14, O04, C03, I05. */
function exchangeConclusionOf(
  answer: AnswerClass,
  context: WireContext,
  kind: TransportMaterial['kind'],
): AnswerConclusion | undefined {
  switch (answer) {
    case 'unsent':
      return settle(NOT_SENT, kind === 'stdio' ? 'stream-broken' : undefined)
    case 'silent':
      // D13: on stdio the probe time ran out; a close or signal settles without a class (T5).
      return settle(
        kind === 'stdio' && PROBE_REQUESTS.includes(context.request) ? LEGACY_PEER : ABANDONED,
      )
    case 'stream-broken':
    case 'http:2xx':
      return settle(
        brokenStream(resends(context, kind)),
        kind === 'stdio' ? 'stream-broken' : undefined,
      )
    case 'process-exited':
      return settle({ kind: 'no-answer', cause: 'process-exited', resend: false }, 'process-exited')
    default:
      return httpStatusConclusionOf(answer)
  }
}

/** The HTTP status rows that read no message: S05, S06, S07 (the rest return undefined). */
function httpStatusConclusionOf(answer: AnswerClass): AnswerConclusion | undefined {
  switch (answer) {
    case 'http:401':
    case 'http:403+scope':
      return AUTHORIZATION_REQUIRED
    case 'http:403':
      return settle(NOT_SENT)
    case 'http:404+session':
      return settle({ kind: 'not-sent', failure: SESSION_ENDED }, 'session-ended')
    default:
      return undefined
  }
}

/** D15, O05: a read request on Streamable HTTP outside the SSE mode is sent once more. */
function resends(context: WireContext, kind: TransportMaterial['kind']): boolean {
  return (
    kind === 'streamable-http' &&
    context.mode !== 'sse' &&
    RESENT_REQUESTS.includes(context.request)
  )
}

function isErrorClass(text: string): text is ErrorClass {
  return ERROR_CLASSES.some(known => known === text)
}

function isStatusClass(text: string): text is HttpStatusClass {
  return HTTP_STATUS_CLASSES.some(known => known === text)
}

/** The parts of a result, error or HTTP error-status class. */
type AnswerParts =
  | Readonly<{ kind: 'result' }>
  | Readonly<{ kind: 'error'; errorClass: ErrorClass }>
  | Readonly<{ kind: 'http'; status: HttpStatusClass; body: BodyClass }>

function partsOf(answer: AnswerClass): AnswerParts {
  if (answer.startsWith('result')) return { kind: 'result' }
  const error = answer.startsWith('error:') ? answer.slice('error:'.length) : undefined
  if (error !== undefined && isErrorClass(error)) return { kind: 'error', errorClass: error }
  const plus = answer.indexOf('+')
  const status = answer.slice('http:'.length, plus)
  const body = answer.slice(plus + 1)
  if (isStatusClass(status) && (body === 'plain' || isErrorClass(body)))
    return { kind: 'http', status, body }
  throw new TypeError(`${answer} is not an answer class of a message`)
}

/** The message a result or error class was read from: its absence is a defect of the caller. */
function messageOf(classified: Extract<WireClassification, { kind: 'answer' }>): JsonObject {
  if (classified.message === undefined)
    throw new TypeError(`the class ${classified.answer} came without its message`)
  return classified.message
}

/** The error object of a message whose envelope (T2) carries `error`, else the whole message (C02). */
function errorPayloadOf(message: JsonObject): JsonValue {
  const envelope = envelopeOf(message)
  return envelope !== undefined && 'error' in envelope ? envelope.error : message
}

function resultWireOf(message: JsonObject): WireAnswer {
  const result = member(message, 'result')
  if (result === undefined) throw new TypeError('a result class came without a result')
  return { kind: 'result', result }
}

function errorWireOf(message: JsonObject, errorClass: ErrorClass): WireAnswer {
  return { kind: 'error', error: errorPayloadOf(message), errorClass }
}

/**
 * An HTTP error status (T8): a probe reads 5xx as a broken stream (D16), a modern-revision error
 * in a 4xx body as the answer (D04–D08) and anything else as a legacy peer (D12); every other
 * request reads a JSON-RPC error in the body as the answer, 5xx+plain as a broken stream that
 * is not re-sent (I06, O07, C04), and 4xx+plain as not sent (O08, C05), or on `initialize`
 * outside the SSE mode as the chance of the legacy HTTP+SSE fallback (I07).
 */
function httpErrorWireOf(
  status: HttpStatusClass,
  body: BodyClass,
  message: JsonObject | undefined,
  context: WireContext,
): WireAnswer {
  const probe = PROBE_REQUESTS.includes(context.request)
  if (status === '5xx' && (probe || body === 'plain')) return brokenStream(false)
  if (body === 'plain') {
    if (probe) return LEGACY_PEER
    return context.request === 'initialize' && context.mode !== 'sse' ? LEGACY_HTTP : NOT_SENT
  }
  if (probe && !MODERN_ERROR_CLASSES.includes(body)) return LEGACY_PEER
  if (message === undefined) throw new TypeError(`the class ${body} came without its message`)
  return errorWireOf(message, body)
}

/**
 * Draws the T8 conclusion of one classification for one request. A classification that is no
 * answer (`other`, `waiting`) is `wait`. A result or error class must carry the message it was
 * read from: `classifyWireEvent` always does; a caller that builds one without it gets a
 * `TypeError`.
 */
export function concludeAnswer(
  classified: WireClassification,
  context: WireContext,
  kind: TransportMaterial['kind'],
): AnswerConclusion {
  if (classified.kind !== 'answer') return WAIT
  const exchange = exchangeConclusionOf(classified.answer, context, kind)
  if (exchange !== undefined) return exchange
  const parts = partsOf(classified.answer)
  switch (parts.kind) {
    case 'result':
      return settle(resultWireOf(messageOf(classified)))
    case 'error':
      return settle(errorWireOf(messageOf(classified), parts.errorClass))
    case 'http':
      return settle(httpErrorWireOf(parts.status, parts.body, classified.message, context))
    default: {
      const exhaustive: never = parts
      return exhaustive
    }
  }
}

/** The failure an error answer reports: the error as written, or `error-shape` when it is unreadable (T7). */
export function errorFailureOf(wire: Extract<WireAnswer, { kind: 'error' }>): TransportFailure {
  const answer = errorAnswerOf(wire.error)
  if (wire.errorClass === 'unreadable' || answer === undefined) return malformed('error-shape')
  return answer
}

// ---- The probe and the two paths of discover (T3, T8 D rows, I rows) ----

/**
 * The highest version in common with the `supported` of a `-32022`, when there is one (T3).
 * `versions` are the modern versions this side speaks, so a legacy version in `supported` is
 * never in common; the modern-ness is judged once, in `errorClassOf` (T2).
 */
export function retryVersionOf(error: JsonValue, versions: readonly string[]): string | undefined {
  const data = isObject(error) ? member(error, 'data') : undefined
  const supported = supportedOf(data) ?? []
  return versions.find(version => supported.includes(version))
}

/** D04–D07: what a `-32022` means, by its class and by which probe it answered. */
function unsupportedVersionOf(
  wire: Extract<WireAnswer, { kind: 'error' }>,
  request: 'discover' | 'discover-retry',
  versions: readonly string[],
): ProbeConclusion {
  if (request === 'discover-retry') return { kind: 'final', failure: errorFailureOf(wire) }
  switch (wire.errorClass) {
    case '-32022+common': {
      const version = retryVersionOf(wire.error, versions)
      return version === undefined
        ? { kind: 'final', failure: malformed('discover-shape') }
        : { kind: 'retry', version }
    }
    case '-32022+modern':
      return { kind: 'final', failure: malformed('discover-shape') }
    default:
      return { kind: 'legacy-peer' }
  }
}

/** A JSON-RPC error on `server/discover`, direct or in a 4xx body (D04–D11). */
function probeErrorConclusionOf(
  wire: Extract<WireAnswer, { kind: 'error' }>,
  request: 'discover' | 'discover-retry',
  versions: readonly string[],
): ProbeConclusion {
  switch (wire.errorClass) {
    case '-32022+common':
    case '-32022+modern':
    case '-32022+legacy':
      return unsupportedVersionOf(wire, request, versions)
    case '-32020':
    case '-32021':
      return { kind: 'final', failure: errorFailureOf(wire) }
    case '-32601':
      return { kind: 'legacy-peer' }
    case '-32602':
    case 'other':
    case 'unreadable':
      return { kind: 'fallback', failure: errorFailureOf(wire) }
    default: {
      const exhaustive: never = wire.errorClass
      return exhaustive
    }
  }
}

/** The failure of a `no-answer`, with its cause and, when it carries one, its mark (T1). */
export function noAnswerFailureOf(
  wire: Extract<WireAnswer, { kind: 'no-answer' }>,
): Extract<TransportFailure, { kind: 'no-answer' }> {
  const { cause, unusable } = wire
  return unusable === undefined
    ? { kind: 'no-answer', cause }
    : { kind: 'no-answer', cause, unusable }
}

/** What one answer to `server/discover` means for the modern path (T3, T8 D01–D16). */
export function concludeProbe(
  wire: WireAnswer,
  request: 'discover' | 'discover-retry',
  versions: readonly string[],
  bound: IdentityBound,
): ProbeConclusion {
  switch (wire.kind) {
    case 'result': {
      const read = readDiscoverResult(wire.result, versions)
      if ('ok' in read) return { kind: 'identity', identity: peerIdentityOf(read.ok, bound) }
      if (read.failure === 'no-common-version') return { kind: 'legacy-peer' }
      return { kind: 'fallback', failure: malformed('discover-shape') }
    }
    case 'error':
      return probeErrorConclusionOf(wire, request, versions)
    case 'no-answer':
      return { kind: 'final', failure: noAnswerFailureOf(wire) }
    case 'not-sent':
      return { kind: 'final', failure: wire.failure }
    case 'legacy-http':
      return { kind: 'final', failure: NOT_SENT_FAILURE }
    case 'legacy-peer':
      return { kind: 'legacy-peer' }
    default: {
      const exhaustive: never = wire
      return exhaustive
    }
  }
}

// ---- What a request settles with after a stream is gone, or a refused authorization (T8, T4) ----

/**
 * T8 S01–S04 and the SSE mode: what every request handed to a shared stream settles with when the
 * stream is gone (`stream-broken`, `process-exited`): `no-answer` with the cause, never sent again,
 * and the transport not usable any more for the same cause (T1).
 */
export function streamGoneAnswerOf(cause: Exclude<UnusableCause, 'session-ended'>): WireAnswer {
  return { kind: 'no-answer', cause, resend: false, unusable: cause }
}

/** T4: what a request refused with 401 or a scoped 403 settles with, given its discovery (R4). */
export function authorizationRequiredAnswerOf(discovery: AuthorizationDiscovery): WireAnswer {
  return {
    kind: 'not-sent',
    failure: { kind: 'not-sent', cause: 'authorization-required', discovery },
  }
}

// ---- The phase of a request in flight, and what a stop or a gone line settles it with (T5, T8) ----

/**
 * The phase of a request in flight (T5). The boundary is what the peer may have received:
 * - `authorizing`: registered, not handed out yet: the peer may not have received any part of it.
 * - `sent`: handed out: the peer may have received it, even when it has not left this process.
 * - `discovery`: refused with 401 or a scoped 403 (T4) and discovering the authorization; `soFar()`
 *   is the discovery from what was fetched by now (R4).
 */
export type InFlightPhase =
  | Readonly<{ kind: 'authorizing' }>
  | Readonly<{ kind: 'sent' }>
  | Readonly<{ kind: 'discovery'; soFar(): AuthorizationDiscovery }>

/**
 * T5: what the caller's signal or `close()` settles a request in flight with, by its phase, there
 * and then: `not-sent` (`connection-unavailable`) while authorizing, `no-answer` (`abandoned`)
 * once sent, `not-sent` (`authorization-required`) with what was fetched by now while discovering.
 */
export function stopAnswerOf(phase: InFlightPhase): WireAnswer {
  switch (phase.kind) {
    case 'authorizing':
      return NOT_SENT
    case 'sent':
      return ABANDONED
    case 'discovery':
      return authorizationRequiredAnswerOf(phase.soFar())
    default: {
      const exhaustive: never = phase
      return exhaustive
    }
  }
}

/**
 * T8 S01–S04, X02, the SSE mode and S07: what a request in flight settles with when the line is gone,
 * by its phase. Only the two phases that depend on the line settle: one still authorizing never
 * reached the wire and is `not-sent` (`connection-unavailable`); one sent answers `no-answer` with
 * the cause, except when the peer ended the session (S07): the request that was told so settled
 * by its row, every other sent request is left to its own answer. Both carry the cause as the mark
 * that the transport is not usable any more (T1). A request discovering its authorization goes on:
 * its conclusion came first (T4), and the discovery does not use the line. Undefined when the
 * request goes on.
 */
export function lineGoneAnswerOf(
  phase: InFlightPhase,
  cause: UnusableCause,
): WireAnswer | undefined {
  switch (phase.kind) {
    case 'authorizing':
      return unusableAnswerOf(NOT_SENT, cause)
    case 'sent':
      return cause === 'session-ended' ? undefined : streamGoneAnswerOf(cause)
    case 'discovery':
      return undefined
    default: {
      const exhaustive: never = phase
      return exhaustive
    }
  }
}

/**
 * T3: the status of the legacy HTTP+SSE fallback GET is classified as an answer to `initialize`
 * outside the SSE mode: 401 and a scoped 403 are S05 (`authorization-required`, the refusal flow of
 * T4); every other status is I07's `not-sent` (`connection-unavailable`).
 */
export function fallbackGetConclusionOf(
  answer: Readonly<{ status: number; headers: Readonly<{ [name: string]: string }>; body: string }>,
  versions: ProtocolVersions,
): Extract<AnswerConclusion, { kind: 'settle' | 'authorization-required' }> {
  const context: WireContext = { id: '', request: 'initialize', session: false, versions }
  const { status, headers, body } = answer
  const conclusion = concludeAnswer(
    classifyWireEvent({ kind: 'http-status', status, headers, body }, context),
    context,
    'streamable-http',
  )
  return conclusion.kind === 'authorization-required'
    ? conclusion
    : { kind: 'settle', wire: NOT_SENT }
}

src/testing-scripted-transport.ts.source:
// An in-memory transport that answers from a `PeerScript`. It composes the JSON-RPC requests that
// SPEC T3 names (request ids, the `_meta` envelope, the progress token) with the contract's one
// implementation, turns each scripted reply into the wire event a real line would report,
// classifies it with `classifyWireEvent` and takes the conclusion of the decision layer. A request
// is registered before it is authorized; the caller's signal and `close()` settle it by its phase
// with the contract's one rule (T5). It keeps only the in-memory wire and its in-flight table, and
// records what the peer received. It does not speak a protocol and is not a product transport.
import type { JsonValue } from '@omne-harness/json-text'
import type { Outcome } from '@omne-harness/operation-result'
import { callAnswerOf, legacyIdentityOf } from './answer-readings.ts'
import { authorizationChallengeOf, startAuthorizationDiscovery } from './authorization.ts'
import type { Generation, TaskId } from './brands.ts'
import {
  OFFERED_LEGACY_VERSION,
  callRequestOf,
  cancelTaskRequest,
  getTaskRequest,
  getTaskResultRequest,
  legacyInitializeParamsOf,
  listActionsRequest,
  notificationTextOf,
  peerRequestAnswerOf,
  requestMetaOf,
  requestTextOf,
  responseTextOf,
  updateTaskRequest,
  type ComposedRequest,
  type NotificationMethod,
  type RequestMethod,
} from './composition.ts'
import { cancelsByNotification, type ConnectionView } from './connection.ts'
import {
  NOT_SENT_FAILURE,
  authorizationRequiredAnswerOf,
  concludeAnswer,
  lineGoneAnswerOf,
  notSentFailureOf,
  requestClassOf,
  stopAnswerOf,
  unusableAnswerOf,
  type AnswerConclusion,
  type ProtocolVersions,
  type UnusableCause,
  type WireAnswer,
} from './decisions.ts'
import { discoverWith, withOneResend } from './discovery.ts'
import { clientEnvelopeOf, mcpRequestHeadersOf, type ClientInfo } from './envelope.ts'
import type { AuthorizationDiscovery, TaskReport } from './outcomes.ts'
import { isPlainJson, isPlainRecord, type PlainJson, type PlainRecord } from './plain.ts'
import type { HttpCredentialHandle } from './ports.ts'
import type { IdentityBound } from './readers.ts'
import { isModernProtocolVersion } from './revisions.ts'
import type {
  PeerNotificationScript,
  PeerReceived,
  PeerReply,
  PeerScript,
  Replies,
} from './testing-transport.ts'
import { jsonOf } from './testing-values.ts'
import type {
  CallRequest,
  ListingPage,
  McpTransport,
  McpTransportFactory,
  PeerNotification,
  SentCall,
  TaskAnswer,
  TransportFailure,
  TransportMaterial,
} from './transport.ts'
import type { PeerIdentity } from './values.ts'
import { classifyWireEvent, type RequestClass, type WireContext, type WireEvent } from './wire.ts'

export type ScriptedTransportOptions = Readonly<{
  /**
   * The modern versions the transport speaks on `server/discover`, highest first. A legacy version
   * here is a `RangeError`: the legacy path offers `LEGACY_PROTOCOL_VERSIONS`. Default:
   * `['2026-07-28']`.
   */
  protocolVersions?: readonly string[]
  clientInfo?: Readonly<{ name: string; version: string }>
  /** How long a stdio `server/discover` waits before the peer counts as legacy. Default: 0. */
  probeTimeoutMs?: number
  /** Awaited before the peer answers each request: a test orders answers with it. */
  pace?: (received: PeerReceived) => Promise<void> | void
}>

export type ScriptedTransportFactory = McpTransportFactory &
  Readonly<{
    /** What the peer received so far, in order. */
    received(): readonly PeerReceived[]
  }>

type Request = Extract<PeerReceived, { kind: 'request' }>
type Headers = Readonly<{ [name: string]: string }>

const DEFAULT_CLIENT_INFO: ClientInfo = { name: 'scripted-transport', version: '0' }

/** The plain record a message of this side reads as, the way the peer would read it. */
function plainRecordOf(text: string): PlainRecord {
  const parsed: unknown = JSON.parse(text)
  if (!isPlainJson(parsed) || !isPlainRecord(parsed))
    throw new TypeError('a message of this side did not write as a JSON object')
  return parsed
}

function isList(value: Replies): value is readonly PeerReply[] {
  return Array.isArray(value)
}

const SILENT: PeerReply = { kind: 'silent' }

/** The peer: picks the scripted reply for each request, in order, and records what it saw. */
class ScriptedPeer {
  readonly log: PeerReceived[] = []
  private readonly consumed = new Map<string, number>()
  private readonly script: PeerScript
  private readonly versions: readonly string[]

  constructor(script: PeerScript, versions: readonly string[]) {
    this.script = script
    this.versions = versions
  }

  private pick(key: string, replies: Replies | undefined, fallback: PeerReply): PeerReply {
    const list = replies === undefined ? undefined : isList(replies) ? replies : [replies]
    if (list === undefined || list.length === 0) return fallback
    const index = this.consumed.get(key) ?? 0
    this.consumed.set(key, index + 1)
    return list[Math.min(index, list.length - 1)] ?? fallback
  }

  reply(method: string, params: PlainRecord): PeerReply {
    const error = (code: number, message: string): PeerReply => ({
      kind: 'error',
      error: { code, message },
    })
    const text = (key: string) => {
      const value = params[key]
      return typeof value === 'string' ? value : ''
    }
    const task = this.script.tasks?.[text('taskId')]
    switch (method) {
      case 'server/discover':
        return this.pick(method, this.script.discover, {
          kind: 'result',
          result: { supportedVersions: [...this.versions], capabilities: { tools: {} } },
        })
      case 'initialize':
        return this.pick(method, this.script.initialize, error(-32601, 'Method not found'))
      case 'tools/list':
        return this.pick(
          `${method}:${text('cursor')}`,
          this.script.listing?.[text('cursor')],
          error(-32602, 'Unknown cursor'),
        )
      case 'tools/call':
        return this.pick(
          `${method}:${text('name')}`,
          this.script.calls?.[text('name')],
          error(-32602, 'Unknown tool'),
        )
      case 'tasks/get':
        return this.pick(`${method}:${text('taskId')}`, task?.get, error(-32602, 'Task not found'))
      case 'tasks/update':
      case 'tasks/cancel': {
        if (task === undefined) return error(-32602, 'Task not found')
        const scripted = method === 'tasks/update' ? task.update : task.cancel
        return this.pick(`${method}:${text('taskId')}`, scripted, { kind: 'result', result: {} })
      }
      default:
        return error(-32601, 'Method not found')
    }
  }

  wellKnown(url: string): PlainJson | undefined {
    this.log.push({ kind: 'fetch', url })
    return this.script.wellKnown?.[new URL(url).pathname]
  }

  /** The requests the peer sends at a point of the legacy path. */
  peerRequests(at: 'initialize' | 'initialized'): readonly Readonly<{ method: string }>[] {
    return (this.script.peerRequests ?? []).filter(request => (request.at ?? 'initialized') === at)
  }

  /** How the peer answers a notification of the client. */
  notificationReply(method: string): PeerReply | undefined {
    const replies = this.script.notifications
    return replies === undefined ? undefined : this.pick(`notification:${method}`, replies, SILENT)
  }
}

/** What one request settled with: the wire answer, and the headers of an HTTP answer. */
type Answered = Readonly<{ wire: WireAnswer; headers?: Headers }>

const NOT_SENT: Answered = { wire: { kind: 'not-sent', failure: NOT_SENT_FAILURE } }

/**
 * The phase of a request in flight (T5), with what each phase holds: the stdio probe time once
 * sent, and the headers of the refusal with the abort of its discovery once discovering.
 */
type Phase =
  | Readonly<{ kind: 'authorizing' }>
  | Readonly<{ kind: 'sent'; cancelProbe(): void }>
  | Readonly<{
      kind: 'discovery'
      headers: Headers
      soFar(): AuthorizationDiscovery
      abort(): void
    }>

const AUTHORIZING: Phase = { kind: 'authorizing' }

/**
 * One request in flight: registered before anything is awaited, with its own settlement (what a
 * caller waits on) and its departure (when the peer took it: what `call` waits on, with the
 * settlement, whichever comes first). A defect of the script fails the settlement.
 */
type Pending = {
  readonly id: string
  readonly context: WireContext
  readonly answered: Promise<Answered>
  readonly resolve: (answered: Answered) => void
  readonly fail: (defect: unknown) => void
  readonly departed: Promise<void>
  readonly depart: () => void
  readonly observe?: (notification: PeerNotification) => void
  readonly progressToken: string
  phase: Phase
}

/** How one request is sent: the observer of a call, the `_meta` version, the probe time. */
type Dispatch = Readonly<{
  observe?: (notification: PeerNotification) => void
  version?: string
  request?: RequestClass
  probeTimeoutMs?: number
  /** Params the caller wrote as value trees, written as they are (RFC-0010). */
  values?: Readonly<{ [key: string]: JsonValue }>
}>

/** The headers of an HTTP reply by lower-case name. */
function lowerCased(headers: Headers | undefined): Headers {
  return Object.fromEntries(
    Object.entries(headers ?? {}).map(([name, value]) => [name.toLowerCase(), value]),
  )
}

/** The wire event a reply makes for the request `id` on the material (T8). */
function eventOf(reply: PeerReply, id: string, stdio: boolean): WireEvent | undefined {
  const message = (member: Readonly<{ [key: string]: PlainJson }>): WireEvent => {
    const text = JSON.stringify({ jsonrpc: '2.0', id, ...member })
    return stdio ? { kind: 'line', text } : { kind: 'http-stream', messages: [text], ended: true }
  }
  switch (reply.kind) {
    case 'result':
      return message({ result: reply.result })
    case 'error':
      return message({ error: reply.error })
    case 'stream-breaks':
      return stdio ? { kind: 'stdio-ended', stdoutEndedAt: 0 } : { kind: 'http-aborted' }
    case 'process-exits':
      return { kind: 'stdio-ended', stdoutEndedAt: 0, exitedAt: 0 }
    case 'http':
      return httpEventOf(reply)
    case 'silent':
    case 'unsent':
      return undefined
    default: {
      const exhaustive: never = reply
      return exhaustive
    }
  }
}

/** The wire event of an HTTP reply: a 2xx body stream, or an error status with its body. */
function httpEventOf(reply: Extract<PeerReply, { kind: 'http' }>): WireEvent {
  if (reply.status < 200)
    throw new TypeError(`script: an http ${reply.status} reply is not observable`)
  if (reply.status < 300)
    return {
      kind: 'http-stream',
      messages: reply.body === undefined ? [] : [reply.body],
      ended: true,
    }
  return {
    kind: 'http-status',
    status: reply.status,
    headers: lowerCased(reply.headers),
    body: reply.body ?? '',
  }
}

/**
 * Whether the peer may have received a request answered with `reply`: everything but a request
 * that fails before it leaves, and an HTTP error status, which settles the request before any
 * answer stream began (T5: the boundary of `sent`).
 */
function departs(reply: PeerReply): boolean {
  if (reply.kind === 'unsent') return false
  return reply.kind !== 'http' || reply.status < 300
}

/** One transport opened on one material, against the scripted peer. */
class ScriptedTransport implements McpTransport {
  readonly generation: Generation
  /** The requests in flight: an entry leaves the table when it settles, and only then. */
  private readonly pending = new Map<string, Pending>()
  /** The ids of the requests that the credential handle authorized. */
  private readonly authorized = new Set<string>()
  private nextId = 0
  private peerRequestCount = 0
  private version: string | undefined
  private closed = false
  private dead: UnusableCause | undefined
  /** The `Mcp-Session-Id` of a legacy Streamable HTTP connection. */
  private session: string | undefined
  private readonly peer: ScriptedPeer
  private readonly material: TransportMaterial
  private readonly options: ScriptedTransportOptions
  private readonly versions: ProtocolVersions

  constructor(
    peer: ScriptedPeer,
    material: TransportMaterial,
    options: ScriptedTransportOptions,
    versions: ProtocolVersions,
  ) {
    this.peer = peer
    this.material = material
    this.options = options
    this.versions = versions
    this.generation = material.generation
  }

  private get stdio(): boolean {
    return this.material.kind === 'stdio'
  }

  private get clientInfo(): ClientInfo {
    return this.options.clientInfo ?? DEFAULT_CLIENT_INFO
  }

  /** The `_meta` envelope (T3), by the contract's one implementation. */
  private envelope(version = this.version ?? this.versions[0]): PlainRecord {
    return clientEnvelopeOf(version, this.clientInfo)
  }

  /** The material facts that bind the peer instructions (T3, S3). */
  private get bound(): IdentityBound {
    return {
      generation: this.generation,
      instructionsByteLimit: this.material.instructionsByteLimit,
    }
  }

  private get usable(): boolean {
    return !this.closed && this.dead === undefined
  }

  private get credential(): HttpCredentialHandle | undefined {
    return this.material.kind === 'streamable-http' ? this.material.credential : undefined
  }

  /** The connection as the T2 and T5 rules see it. */
  private get connection(): ConnectionView {
    return this.material.kind === 'stdio'
      ? { kind: 'stdio', version: this.version }
      : { kind: 'streamable-http', version: this.version, mode: 'streamable' }
  }

  private reserveId(): string {
    this.nextId += 1
    return `r${this.nextId}`
  }

  private headersOf(method: string, params: PlainRecord, version: string) {
    return this.material.kind === 'streamable-http'
      ? { headers: mcpRequestHeadersOf(method, params, version, this.session) }
      : {}
  }

  // ---- The requests in flight: registration, the phases, and what settles them ----

  /**
   * Once the transport is not usable any more, every answer it hands over carries the cause it
   * recorded (T1, T8 "every later request"); after `close()` none does: closing is this side's
   * decision, not a fact about the line.
   */
  private handedOver(answered: Answered): Answered {
    if (this.closed || this.dead === undefined) return answered
    return { ...answered, wire: unusableAnswerOf(answered.wire, this.dead) }
  }

  /** The `not-sent` of a request the transport did not take: closed, not usable, or stopped first. */
  private get refused(): Extract<TransportFailure, { kind: 'not-sent' }> {
    return notSentFailureOf(this.closed ? undefined : this.dead)
  }

  private settle(entry: Pending, answered: Answered): void {
    if (!this.pending.delete(entry.id)) return
    if (entry.phase.kind === 'sent') entry.phase.cancelProbe()
    entry.resolve(this.handedOver(answered))
  }

  /** Stops a request where it stands (T5): the caller's signal fired, `cancelRequest` or `close()` ran. */
  private stop(entry: Pending): void {
    if (!this.pending.has(entry.id)) return
    const phase = entry.phase
    if (phase.kind === 'discovery') phase.abort()
    this.settle(
      entry,
      phase.kind === 'discovery'
        ? { wire: stopAnswerOf(phase), headers: phase.headers }
        : { wire: stopAnswerOf(phase) },
    )
  }

  /** The transport is unusable from now on; every request in flight settles by its phase (T8). */
  private unusable(cause: UnusableCause): void {
    this.dead ??= cause
    for (const entry of this.pending.values()) {
      const wire = lineGoneAnswerOf(entry.phase, cause)
      if (wire !== undefined) this.settle(entry, { wire })
    }
  }

  /**
   * Registers one request and starts its sending in the background; the caller waits on the
   * settlement. Undefined when the transport cannot be used: nothing is registered.
   */
  private begin(
    method: RequestMethod,
    params: PlainRecord,
    how: Dispatch,
    signal?: AbortSignal,
  ): Pending | undefined {
    if (!this.usable) return undefined
    const id = this.reserveId()
    const context: WireContext = {
      id,
      request: how.request ?? requestClassOf(method, false),
      session: this.session !== undefined && method !== 'initialize',
      versions: this.versions,
    }
    const answered = Promise.withResolvers<Answered>()
    const departed = Promise.withResolvers<void>()
    const entry: Pending = {
      id,
      context,
      answered: answered.promise,
      resolve: answered.resolve,
      fail: answered.reject,
      departed: departed.promise,
      depart: departed.resolve,
      ...(how.observe === undefined ? {} : { observe: how.observe }),
      progressToken: id,
      phase: AUTHORIZING,
    }
    this.pending.set(id, entry)
    if (signal !== undefined) this.wireSignal(entry, signal)
    void this.send(entry, method, params, how)
    return entry
  }

  /** Wires the call's signal to the entry: once it fires, the entry is stopped where it stands (T5). */
  private wireSignal(entry: Pending, signal: AbortSignal): void {
    const onAbort = () => this.stop(entry)
    if (signal.aborted) return onAbort()
    signal.addEventListener('abort', onAbort, { once: true })
    const unwire = () => signal.removeEventListener('abort', onAbort)
    void entry.answered.then(unwire, unwire)
  }

  /**
   * The sending of one request: authorizes it, then hands it to the peer. An entry stopped
   * meanwhile is left as it settled. A defect of the script fails the settlement.
   */
  private async send(
    entry: Pending,
    method: RequestMethod,
    params: PlainRecord,
    how: Dispatch,
  ): Promise<void> {
    try {
      if (!(await this.authorize(entry.id))) return this.settle(entry, NOT_SENT)
      if (!this.pending.has(entry.id)) return
      this.dispatch(entry, method, params, how)
    } catch (defect) {
      this.pending.delete(entry.id)
      entry.fail(defect)
    }
  }

  /** Composes the request, records it, and lets the peer answer after the pace hook. */
  private dispatch(
    entry: Pending,
    method: RequestMethod,
    params: PlainRecord,
    how: Dispatch,
  ): void {
    const id = entry.id
    const version = how.version ?? this.version ?? this.versions[0]
    const meta = requestMetaOf(method, id, version, this.clientInfo)
    const written = plainRecordOf(
      requestTextOf({ id, method, params: { ...params, _meta: meta }, values: how.values ?? {} }),
    )
    const sent = isPlainRecord(written['params']) ? written['params'] : {}
    const request: Request = {
      kind: 'request',
      id,
      method,
      params: sent,
      ...this.headersOf(method, params, version),
    }
    const reply = this.peer.reply(method, sent)
    this.validate(reply, method)
    entry.phase = { kind: 'sent', cancelProbe: () => undefined }
    if (reply.kind === 'unsent') {
      // The request fails before it leaves; the peer does not see it (T8 X01, X02).
      return this.apply(
        entry,
        concludeAnswer(
          classifyWireEvent({ kind: 'unsent' }, entry.context),
          entry.context,
          this.material.kind,
        ),
        {},
      )
    }
    this.peer.log.push(request)
    if (departs(reply)) entry.depart()
    void this.deliver(request, reply, entry, how.probeTimeoutMs)
  }

  /** A reply the material cannot carry is a defect of the script, reported at once. */
  private validate(reply: PeerReply, method: string): void {
    if (reply.kind === 'http' && this.stdio)
      throw new TypeError(`script: an http reply to ${method} on stdio material`)
    if (reply.kind === 'process-exits' && !this.stdio)
      throw new TypeError(`script: a process-exits reply to ${method} on streamable-http material`)
  }

  /** D13: starts the stdio probe time of `server/discover`; an answer before it ends clears it. */
  private startProbe(entry: Pending, milliseconds: number): void {
    const probe = setTimeout(() => {
      const conclusion = concludeAnswer(
        classifyWireEvent({ kind: 'nothing' }, entry.context),
        entry.context,
        this.material.kind,
      )
      this.apply(entry, conclusion, {})
    }, milliseconds)
    entry.phase = { kind: 'sent', cancelProbe: () => clearTimeout(probe) }
  }

  /**
   * Answers after the pace hook. The probe time starts only then, so a test that holds the answer
   * does not turn a modern peer into a legacy one. A defect of the script fails the settlement.
   */
  private async deliver(
    request: Request,
    reply: PeerReply,
    entry: Pending,
    probeTimeoutMs: number | undefined,
  ): Promise<void> {
    try {
      await this.options.pace?.(request)
      if (!this.pending.has(request.id)) return
      if (probeTimeoutMs !== undefined) this.startProbe(entry, probeTimeoutMs)
      if (reply.kind === 'result')
        for (const notification of reply.notifications ?? []) this.notify(notification, entry)
      const event = eventOf(reply, request.id, this.stdio)
      if (event === undefined) return
      const headers = lowerCased(
        reply.kind === 'http' || reply.kind === 'result' ? reply.headers : undefined,
      )
      const conclusion = concludeAnswer(
        classifyWireEvent(event, entry.context),
        entry.context,
        this.material.kind,
      )
      this.apply(entry, conclusion, headers)
    } catch (defect) {
      this.pending.delete(entry.id)
      entry.fail(defect)
    }
  }

  /** Settles the request as the T8 row says, and what the row says of the transport. */
  private apply(entry: Pending, conclusion: AnswerConclusion, headers: Headers): void {
    switch (conclusion.kind) {
      case 'wait':
        return
      case 'settle':
        this.settle(entry, { wire: conclusion.wire, headers })
        if (conclusion.unusable !== undefined) this.unusable(conclusion.unusable)
        return
      case 'authorization-required':
        return this.enterDiscovery(entry, headers)
      default: {
        const exhaustive: never = conclusion
        return exhaustive
      }
    }
  }

  /**
   * A notification of the peer during a request. The peer fills in the progress token of the
   * request when the script names none. A progress notification whose token is the token of the
   * call goes to `observe` with its `params` as written; any other notification is dropped.
   */
  private notify(notification: PeerNotificationScript, entry: Pending): void {
    const written = isPlainRecord(notification.params) ? notification.params : {}
    const params =
      written['progressToken'] === undefined
        ? { ...written, progressToken: entry.progressToken }
        : written
    const observe = entry.observe
    if (notification.method !== 'notifications/progress' || observe === undefined) return
    if (params['progressToken'] !== entry.progressToken) return
    try {
      observe({ kind: 'progress', notification: { untrusted: jsonOf(params) } })
    } catch {
      // S6: an observer that throws does not change the outcome.
    }
  }

  /**
   * T4: the request was refused. `reportRejection` once on the handle that authorized it, and the
   * discovery of R4, run in the background; the request settles when both ended, or by its phase
   * when it is stopped first (T5).
   */
  private enterDiscovery(entry: Pending, headers: Headers): void {
    const target = this.material.kind === 'streamable-http' ? this.material.target : undefined
    if (target === undefined)
      throw new TypeError('script: a refused authorization on stdio material')
    const credential = this.credential
    // A handle whose reportRejection rejects or throws is ignored (T9).
    const reported =
      credential !== undefined && this.authorized.has(entry.id)
        ? Promise.resolve()
            .then(() => credential.reportRejection())
            .catch(() => undefined)
        : Promise.resolve()
    const controller = new AbortController()
    const run = startAuthorizationDiscovery(
      target,
      authorizationChallengeOf(headers['www-authenticate']),
      async url => {
        const metadata = this.peer.wellKnown(url)
        return metadata === undefined ? undefined : jsonOf(metadata)
      },
      controller.signal,
    )
    entry.phase = { kind: 'discovery', headers, soFar: run.soFar, abort: () => controller.abort() }
    void Promise.all([reported, run.done]).then(([, discovery]) =>
      this.settle(entry, { wire: authorizationRequiredAnswerOf(discovery), headers }),
    )
  }

  /** Authorizes an outgoing request with the credential handle, when the material has one. */
  private async authorize(id: string): Promise<boolean> {
    const credential = this.credential
    if (credential === undefined) return true
    const headers = new Headers()
    // A handle whose authorize rejects or throws leaves the request not sent (T9).
    const answer = await Promise.resolve()
      .then(() => credential.authorize(headers))
      .catch(() => undefined)
    if (answer === undefined || 'failure' in answer) return false
    this.authorized.add(id)
    return true
  }

  /** Sends one non-call request; the row may send it once more after a broken stream (D15, O05). */
  private request(
    method: RequestMethod,
    params: PlainRecord,
    how: Dispatch = {},
  ): Promise<Answered> {
    return withOneResend(() => this.once(method, params, how))
  }

  /** Sends the request an operation composed and reads its answer the way the operation does. */
  private async perform<T>(composed: ComposedRequest<T>): Promise<Outcome<T, TransportFailure>> {
    const how: Dispatch = composed.values === undefined ? {} : { values: composed.values }
    return composed.read((await this.request(composed.method, composed.params, how)).wire)
  }

  /** Registers one request and waits on its settlement only: never on its sending. */
  private once(method: RequestMethod, params: PlainRecord, how: Dispatch): Promise<Answered> {
    const probe = method === 'server/discover' && this.stdio
    const entry = this.begin(method, params, {
      ...how,
      ...(probe ? { probeTimeoutMs: this.options.probeTimeoutMs ?? 0 } : {}),
    })
    return entry === undefined
      ? Promise.resolve({ wire: { kind: 'not-sent', failure: this.refused } })
      : entry.answered
  }

  /** Sends a notification. Whatever the peer answers to it does not change any outcome (T8 N01). */
  private sendNotification(method: NotificationMethod, params: PlainRecord): void {
    const version = this.version ?? this.versions[0]
    const written = plainRecordOf(
      notificationTextOf({ method, params: { ...params, _meta: this.envelope() } }),
    )
    this.peer.log.push({
      kind: 'notification',
      method,
      params: written['params'] ?? {},
      ...this.headersOf(method, params, version),
    })
    const reply = this.peer.notificationReply(method)
    if (reply === undefined || !this.stdio) return
    if (reply.kind === 'stream-breaks') this.unusable('stream-broken')
    if (reply.kind === 'process-exits') this.unusable('process-exited')
  }

  async discover(): Promise<Outcome<PeerIdentity, TransportFailure>> {
    const discovered = await discoverWith(
      {
        probe: async (version, request) =>
          (await this.request('server/discover', {}, { version, request })).wire,
        legacy: () => this.legacyPath(),
      },
      this.versions,
      this.bound,
    )
    if ('ok' in discovered) this.version = discovered.ok.protocolVersion
    return discovered
  }

  /**
   * The requests of the peer, at one point of the legacy path: `ping` answers an empty result,
   * every other request `-32601` (T3).
   */
  private answerPeerRequests(at: 'initialize' | 'initialized'): void {
    for (const request of this.peer.peerRequests(at)) {
      const id = `p${(this.peerRequestCount += 1)}`
      const answer = peerRequestAnswerOf({
        kind: 'request',
        id: jsonOf(id),
        method: request.method,
      })
      const written = plainRecordOf(responseTextOf({ id: jsonOf(id), ...answer }))
      this.peer.log.push({
        kind: 'response',
        id,
        ...(written['result'] === undefined ? {} : { result: written['result'] }),
        ...(written['error'] === undefined ? {} : { error: written['error'] }),
      })
    }
  }

  /** The legacy path: `initialize` with the highest legacy version, then `notifications/initialized`. */
  private async legacyPath(): Promise<Outcome<PeerIdentity, TransportFailure>> {
    const answered = await this.request('initialize', legacyInitializeParamsOf(this.clientInfo), {
      version: OFFERED_LEGACY_VERSION,
    })
    this.answerPeerRequests('initialize')
    const read = legacyIdentityOf(answered.wire, this.bound)
    if ('failure' in read) return read
    this.version = read.ok.protocolVersion
    if (this.material.kind === 'streamable-http')
      this.session = answered.headers?.['mcp-session-id']
    this.sendNotification('notifications/initialized', {})
    this.answerPeerRequests('initialized')
    return read
  }

  async listActions(cursor?: string): Promise<Outcome<ListingPage, TransportFailure>> {
    return this.perform(listActionsRequest(cursor, this.connection))
  }

  /**
   * `call` waits for the request to reach the peer or to settle, whichever comes first (T5): a
   * `SentCall` once the peer may have received it, `not-sent` as the call's own failure when it
   * settled so before.
   */
  async call(
    request: CallRequest,
    signal: AbortSignal,
    observe?: (notification: PeerNotification) => void,
  ): Promise<Outcome<SentCall, Extract<TransportFailure, { kind: 'not-sent' }>>> {
    if (signal.aborted) return { failure: this.refused }
    const composed = callRequestOf(request)
    const entry = this.begin(
      composed.method,
      composed.params,
      { values: composed.values, ...(observe === undefined ? {} : { observe }) },
      signal,
    )
    if (entry === undefined) return { failure: this.refused }
    const first = await Promise.race([entry.departed.then(() => undefined), entry.answered])
    if (first?.wire.kind === 'not-sent') return { failure: first.wire.failure }
    return {
      ok: {
        requestId: entry.id,
        answer: entry.answered.then(answered => callAnswerOf(answered.wire)),
      },
    }
  }

  /**
   * T5, by the contract's `cancelsByNotification`: the notification, or the request is stopped by
   * its phase with the contract's one rule (`stopAnswerOf`), as the caller's signal and `close()`
   * stop it. Only a request handed to the peer has an answer stream to end.
   */
  async cancelRequest(requestId: string): Promise<void> {
    if (cancelsByNotification(this.connection)) {
      this.sendNotification('notifications/cancelled', { requestId })
      return
    }
    const entry = this.pending.get(requestId)
    if (entry === undefined) return
    if (entry.phase.kind === 'sent') this.peer.log.push({ kind: 'stream-aborted', id: requestId })
    this.stop(entry)
  }

  getTask(taskId: TaskId): Promise<Outcome<TaskReport | 'expired', TransportFailure>> {
    return this.perform(getTaskRequest(taskId))
  }

  getTaskResult(taskId: TaskId): Promise<Outcome<TaskAnswer, TransportFailure>> {
    return this.perform(getTaskResultRequest(taskId))
  }

  updateTask(
    taskId: TaskId,
    inputResponses: JsonValue,
  ): Promise<Outcome<'accepted', TransportFailure>> {
    return this.perform(updateTaskRequest(taskId, inputResponses))
  }

  cancelTask(taskId: TaskId): Promise<Outcome<'requested', TransportFailure>> {
    return this.perform(cancelTaskRequest(taskId))
  }

  /** Closes the transport (T5): every request in flight settles by its phase there and then. */
  async close(): Promise<void> {
    if (this.closed) return
    this.closed = true
    for (const entry of this.pending.values()) this.stop(entry)
    if (this.material.kind !== 'stdio') return
    const { stdin, stdout } = this.material.process
    await stdin.close().catch(() => undefined)
    await stdout.cancel().catch(() => undefined)
  }
}

function isProtocolVersions(versions: readonly string[]): versions is ProtocolVersions {
  return versions.length > 0
}

/**
 * A transport factory whose peer answers from the script, in memory. It records what the peer
 * received, `_meta` and progress tokens included. Every transport it opens shares the one peer,
 * so the script is consumed in request order across transports.
 */
export function createScriptedTransportFactory(
  script: PeerScript,
  options: ScriptedTransportOptions = {},
): ScriptedTransportFactory {
  const versions = options.protocolVersions ?? ['2026-07-28']
  if (!isProtocolVersions(versions) || !versions.every(isModernProtocolVersion))
    throw new RangeError(
      'protocolVersions lists the modern versions only; the legacy ones are LEGACY_PROTOCOL_VERSIONS',
    )
  const peer = new ScriptedPeer(script, versions)
  return {
    received: () => [...peer.log],
    async open(material, signal) {
      if (signal.aborted) return { failure: NOT_SENT_FAILURE }
      return { ok: new ScriptedTransport(peer, material, options, versions) }
    },
  }
}

