tests/json-equality.spec.ts.source:
import { describe, expect, it } from 'vitest'
import { writeJsonText } from '@omne-harness/json-text'
import { canonical, sameJson } from '@omne-harness/mcp-contract'
import { json, jsonText } from './json.ts'

describe('canonical and sameJson', () => {
  it('sorts object members by name at every depth and keeps number lexemes', () => {
    const tree = jsonText('{"b":{"y":1.0,"x":[{"d":2,"c":3}]},"a":null}')
    expect(writeJsonText(canonical(tree))).toBe('{"a":null,"b":{"x":[{"c":3,"d":2}],"y":1.0}}')
  })

  it('treats trees that differ only in member order as the same', () => {
    expect(sameJson(json({ a: 1, b: { c: 2, d: 3 } }), json({ b: { d: 3, c: 2 }, a: 1 }))).toBe(
      true,
    )
  })

  it('tells apart a different value, a different member and a different number lexeme', () => {
    expect(sameJson(json({ a: 1 }), json({ a: 2 }))).toBe(false)
    expect(sameJson(json({ a: 1 }), json({ a: 1, b: 1 }))).toBe(false)
    expect(sameJson(jsonText('{"a":1}'), jsonText('{"a":1.0}'))).toBe(false)
    expect(sameJson(json([1, 2]), json([2, 1]))).toBe(false)
  })
})

tests/testing-values.spec.ts.source:
// The sample builders of `./testing`: each one answers a branded value for a lawful sample and
// throws `TypeError` for anything its guard refuses, so a bad sample is a defect of the suite.
import { describe, expect, it } from 'vitest'
import {
  isAdoptionRevision,
  isConnectionTarget,
  isCorrelationKey,
  isCredentialBinding,
  isEndpointHolding,
  isEndpointName,
  isMillis,
  isProtocolVersion,
} from '@omne-harness/mcp-contract'
import {
  adoptionRevisionOf,
  connectionTargetOf,
  correlationKeyOf,
  credentialBindingOf,
  endpointRefOf,
  jsonOf,
  millisOf,
  peerIdentityOf,
} from '@omne-harness/mcp-contract/testing'

describe('the sample builders of the brands', () => {
  it('endpointRefOf builds a reference from the name, with a holding under the name by default', () => {
    const ref = endpointRefOf('files')
    expect(ref).toEqual({ name: 'files', holding: 'tenant/files' })
    expect(isEndpointName(ref.name)).toBe(true)
    expect(isEndpointHolding(ref.holding)).toBe(true)
    expect(endpointRefOf('files', 'ws/files')).toEqual({ name: 'files', holding: 'ws/files' })
    expect(() => endpointRefOf('')).toThrow(TypeError)
    expect(() => endpointRefOf('files', '')).toThrow(TypeError)
  })

  it.each([
    ['adoptionRevisionOf', adoptionRevisionOf, isAdoptionRevision, 'rev-1', ''],
    ['credentialBindingOf', credentialBindingOf, isCredentialBinding, 'main', ''],
    ['correlationKeyOf', correlationKeyOf, isCorrelationKey, 'c1', ''],
    [
      'connectionTargetOf',
      connectionTargetOf,
      isConnectionTarget,
      'https://files.example.test/mcp',
      'ftp://files.example.test/',
    ],
  ] as const)(
    '%s answers the guarded text and refuses what the guard refuses',
    (_name, build, guard, lawful, refused) => {
      const built: unknown = build(lawful)
      expect(built).toBe(lawful)
      expect(guard(built)).toBe(true)
      expect(() => build(refused)).toThrow(TypeError)
    },
  )

  it('millisOf answers a positive safe integer of milliseconds and refuses the rest', () => {
    const built: unknown = millisOf(30_000)
    expect(built).toBe(30_000)
    expect(isMillis(built)).toBe(true)
    expect(() => millisOf(0)).toThrow(TypeError)
    expect(() => millisOf(1.5)).toThrow(TypeError)
  })

  it('peerIdentityOf answers the negotiated facts of a modern peer with the tools capability', () => {
    const peer = peerIdentityOf()
    expect(peer).toEqual({ protocolVersion: '2026-07-28', capabilities: jsonOf({ tools: {} }) })
    expect(isProtocolVersion(peer.protocolVersion)).toBe(true)
    expect(peerIdentityOf('2025-06-18').protocolVersion).toBe('2025-06-18')
    expect(() => peerIdentityOf('')).toThrow(TypeError)
  })
})

tests/keys.spec.ts.source:
import { describe, expect, it } from 'vitest'
import {
  accountCodec,
  organizationCodec,
  tenant,
  type TenantId,
} from '@omne-harness/legal-identity'
import {
  catalogKeyOf,
  connectionKeyOf,
  isAdoptionRevision,
  isCredentialBinding,
  isEndpointHolding,
  isEndpointName,
  peerAccountOf,
  type AdoptionRevision,
  type CredentialBinding,
  type PeerAccount,
} from '@omne-harness/mcp-contract'
import type { AdoptedEndpoint } from '@omne-harness/mcp-contract/provider'
import { json } from './json.ts'

function tenantOf(body: string): TenantId {
  const organization = organizationCodec.parse(`org_${body}`)
  const account = accountCodec.parse(`acc_${body}`)
  if (!organization.ok || !account.ok) throw new Error('bad tenant')
  return tenant(organization.value, account.value)
}

function binding(text: string): CredentialBinding {
  if (!isCredentialBinding(text)) throw new Error('bad binding')
  return text
}

function revision(text: string): AdoptionRevision {
  if (!isAdoptionRevision(text)) throw new Error('bad revision')
  return text
}

function endpoint(adoption: AdoptionRevision): AdoptedEndpoint {
  const name = 'files'
  const holding = 'tenant/files'
  if (!isEndpointName(name) || !isEndpointHolding(holding)) throw new Error('bad ref')
  return {
    ref: { name, holding },
    revision: adoption,
    body: json({ name: 'files', transport: 'streamable-http', auth: 'oauth' }),
    settings: { target: absent, credential: absent, connectTimeout: absent },
    processEnv: [],
  }
}

const absent = { kind: 'absent' } as const
const first = tenantOf('0123456789abcdefghjkmnpqrs')
const second = tenantOf('0123456789abcdefghjkmnpqrt')
const alice: PeerAccount = { kind: 'credential', binding: binding('alice') }
const bob: PeerAccount = { kind: 'credential', binding: binding('bob') }

describe('peerAccountOf', () => {
  it('is anonymous without authentication, whatever binding is given', () => {
    expect(peerAccountOf('none', undefined)).toEqual({ ok: { kind: 'anonymous' } })
    expect(peerAccountOf('none', binding('alice'))).toEqual({ ok: { kind: 'anonymous' } })
  })

  it('is the bound credential with authentication', () => {
    expect(peerAccountOf('static', binding('alice'))).toEqual({ ok: alice })
    expect(peerAccountOf('oauth', binding('bob'))).toEqual({ ok: bob })
  })

  it('reports a missing credential instead of falling back to another account', () => {
    expect(peerAccountOf('static', undefined)).toEqual({ failure: 'credential-missing' })
    expect(peerAccountOf('oauth', undefined)).toEqual({ failure: 'credential-missing' })
  })
})

describe('connectionKeyOf', () => {
  const base = connectionKeyOf(first, endpoint(revision('r1')), alice)

  it('is built from the tenant, the holding, the adoption revision and the account', () => {
    expect(base).toEqual({
      tenant: first,
      holding: 'tenant/files',
      adoptionRevision: 'r1',
      account: alice,
    })
  })

  it('differs for another tenant, another account and another adoption revision', () => {
    expect(connectionKeyOf(second, endpoint(revision('r1')), alice)).not.toEqual(base)
    expect(connectionKeyOf(first, endpoint(revision('r1')), bob)).not.toEqual(base)
    expect(connectionKeyOf(first, endpoint(revision('r2')), alice)).not.toEqual(base)
  })
})

describe('catalogKeyOf', () => {
  const base = catalogKeyOf(first, endpoint(revision('r1')), alice)

  it('is built from the tenant, the account and the holding only', () => {
    expect(base).toEqual({ tenant: first, account: alice, holding: 'tenant/files' })
    expect(catalogKeyOf(first, endpoint(revision('r2')), alice)).toEqual(base)
  })

  it('differs for another tenant and another account', () => {
    expect(catalogKeyOf(second, endpoint(revision('r1')), alice)).not.toEqual(base)
    expect(catalogKeyOf(first, endpoint(revision('r1')), bob)).not.toEqual(base)
  })
})

tests/instructions.spec.ts.source:
import { createHash } from 'node:crypto'
import { describe, expect, it } from 'vitest'
import { boundInstructions } from '@omne-harness/mcp-contract'

const sha = (text: string) => `sha256:${createHash('sha256').update(text, 'utf8').digest('hex')}`

describe('boundInstructions', () => {
  it('keeps text within the bound whole', () => {
    expect(boundInstructions('use tools', 9)).toEqual({
      text: 'use tools',
      truncated: false,
      digest: sha('use tools'),
    })
  })

  it('cuts at the byte bound and digests the whole text before the cut', () => {
    expect(boundInstructions('abcdef', 4)).toEqual({
      text: 'abcd',
      truncated: true,
      digest: sha('abcdef'),
    })
  })

  it('does not split a character: a cut inside a multi-byte character drops all of it', () => {
    // 'é' is 2 bytes and '€' is 3 bytes in UTF-8.
    expect(boundInstructions('aé', 2).text).toBe('a')
    expect(boundInstructions('a€b', 3).text).toBe('a')
    expect(boundInstructions('a€b', 4).text).toBe('a€')
    expect(boundInstructions('€', 2)).toMatchObject({ text: '', truncated: true })
  })

  it('throws for a bound that is not a positive safe integer', () => {
    for (const bound of [0, -1, 1.5, Number.NaN])
      expect(() => boundInstructions('a', bound)).toThrow(RangeError)
  })
})
